selector_to_html = {"a[href=\"#module-pyskyfire.common.meridional\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.meridional<a class=\"headerlink\" href=\"#module-pyskyfire.common.meridional\" title=\"Link to this heading\">\u00b6</a></h1><p>The wetted flow path of a turbomachine or annular duct, seen in meridional section.</p><p>A passage is two walls of revolution about the shaft (+x), each given as an\n<code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> curve: the <code class=\"docutils literal notranslate\"><span class=\"pre\">hub</span></code> nearer the axis and the <code class=\"docutils literal notranslate\"><span class=\"pre\">shroud</span></code> outside it.\nBoth curves have the same number of points, and point <code class=\"docutils literal notranslate\"><span class=\"pre\">i</span></code> on one pairs with\npoint <code class=\"docutils literal notranslate\"><span class=\"pre\">i</span></code> on the other. Each pair is the end of a span line, and positions\nalong the passage are fractions of the hub\u2019s arc length. That pairing is what\nlets blade sections be placed at a span fraction, and what an annular duct\nreads its area from.</p>", "a[href=\"AnnulusEnd.html#pyskyfire.common.meridional.AnnulusEnd\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.AnnulusEnd\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.meridional.</span></span><span class=\"sig-name descname\"><span class=\"pre\">AnnulusEnd</span></span></dt><dd><p>One end of a passage: what anything joining it there has to match.</p></dd>", "a[href=\"MeridionalPassage.html#pyskyfire.common.meridional.MeridionalPassage\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.MeridionalPassage\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.meridional.</span></span><span class=\"sig-name descname\"><span class=\"pre\">MeridionalPassage</span></span></dt><dd><p>Paired hub and shroud curves, in <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> metres, inlet to outlet.</p></dd>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"WallMotion.html#pyskyfire.common.meridional.WallMotion\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.WallMotion\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.meridional.</span></span><span class=\"sig-name descname\"><span class=\"pre\">WallMotion</span></span></dt><dd><p>Which stretches of each wall rotate with the shaft.</p><p>Each wall lists the <code class=\"docutils literal notranslate\"><span class=\"pre\">(start,</span> <span class=\"pre\">end)</span></code> station fractions over which it\nturns; everywhere else it stands still. The default is a passage that\nstands still throughout, as a duct does.</p></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#pyskyfire.common.meridional.WALLS\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.WALLS\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.meridional.</span></span><span class=\"sig-name descname\"><span class=\"pre\">WALLS</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">('hub',</span> <span class=\"pre\">'shroud')</span></span></dt><dd></dd>", "a[href=\"Clearance.html#pyskyfire.common.meridional.Clearance\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.common.meridional.Clearance\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.common.meridional.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Clearance</span></span></dt><dd><p>A blade edge that stops short of a passage wall.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
